    Bug 1940193 - Catch and log errors while processing CalDAV item requests. r=mkmelin

    An exception thrown handling one item shouldn't prevent the handling of subsequent items.

    Differential Revision: https://phabricator.services.mozilla.com/D233324

diff --git a/calendar/providers/caldav/CalDavCalendar.sys.mjs b/calendar/providers/caldav/CalDavCalendar.sys.mjs
index bee10870b50..e70010d79b2 100644
--- a/calendar/providers/caldav/CalDavCalendar.sys.mjs
+++ b/calendar/providers/caldav/CalDavCalendar.sys.mjs
@@ -956,10 +956,15 @@ CalDavCalendar.prototype = {
     const isInboxItem = this.isInbox(aUri.spec);

     if (this.mHrefIndex[path] && !this.mItemInfoCache[item.id]) {
-      // If we get here it means a meeting has kept the same filename
-      // but changed its uid, which can happen server side.
-      // Delete the meeting before re-adding it
-      this.deleteTargetCalendarItem(path);
+      try {
+        // If we get here it means a meeting has kept the same filename
+        // but changed its uid, which can happen server side.
+        // Delete the meeting before re-adding it.
+        this.deleteTargetCalendarItem(path);
+      } catch (ex) {
+        // Don't let an exception here prevent us continuing.
+        cal.ERROR(`Delete item FAILED; path=${path}, id=${item.id}`, ex);
+      }
     }

     if (this.mItemInfoCache[item.id]) {
